'use strict';

// Regression tests for INC-5521 (oversold stock and stuck holds during the
// 2026-09-12 flash sale). Most of these fire calls concurrently: the default
// Store yields on every get/set, so concurrent calls interleave the way they
// do against production.

const test = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  OrderStateError
} = require('../src');

async function service(stock = { widget: 10 }, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

function range(n) {
  return Array.from({ length: n }, (_, i) => i);
}

// --- 263 orders confirmed for 250 units -------------------------------------

test('concurrent reserves never hold more than the stock', async () => {
  const svc = await service({ 'sneaker-limited': 250 });
  const results = await Promise.allSettled(
    range(300).map(i => svc.reserve(`o${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
  );
  const held = results.filter(r => r.status === 'fulfilled');
  const refused = results.filter(r => r.status === 'rejected');
  assert.equal(held.length, 250);
  assert.ok(refused.every(r => r.reason instanceof InsufficientStockError));
  assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 250, reserved: 250, sold: 0 });

  await Promise.all(held.map(r => svc.commit(r.value.orderId)));
  assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 0, reserved: 0, sold: 250 });
});

test('commits running alongside reserves on the same sku keep every hold', async () => {
  const svc = await service({ widget: 10 });
  for (const i of range(5)) {
    await svc.reserve(`old${i}`, [{ sku: 'widget', qty: 1 }]);
  }
  await Promise.all([
    ...range(5).map(i => svc.commit(`old${i}`)),
    ...range(5).map(i => svc.reserve(`new${i}`, [{ sku: 'widget', qty: 1 }]))
  ]);
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 5, reserved: 5, sold: 5 });
  await assert.rejects(svc.reserve('one-too-many', [{ sku: 'widget', qty: 1 }]), InsufficientStockError);
});

test('addStock running alongside reserves loses neither', async () => {
  const svc = await service({ widget: 10 });
  await Promise.all([
    ...range(5).map(i => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }])),
    ...range(3).map(() => svc.addStock('widget', 5))
  ]);
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 25, reserved: 5, sold: 0 });
});

test('concurrent addStock calls for a new sku add up', async () => {
  const svc = new InventoryService();
  await Promise.all(range(4).map(() => svc.addStock('widget', 3)));
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 12, reserved: 0, sold: 0 });
});

test('services sharing a store do not oversell', async () => {
  const store = new Store();
  const first = new InventoryService({ store });
  const second = new InventoryService({ store });
  await first.addStock('widget', 10);
  const results = await Promise.allSettled(
    range(20).map(i => (i % 2 ? first : second).reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]))
  );
  assert.equal(results.filter(r => r.status === 'fulfilled').length, 10);
  assert.equal(await first.available('widget'), 0);
});

// --- reserved went negative ---------------------------------------------------

test('a committed order cannot be released', async () => {
  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
  await svc.commit('o1');
  await assert.rejects(svc.release('o1'), OrderStateError);
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
  assert.equal((await svc.commit('o1')).status, 'committed');
});

test('concurrent releases of one order return its units once', async () => {
  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
  const results = await Promise.all(range(3).map(() => svc.release('o1')));
  assert.ok(results.every(r => r.status === 'released'));
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
});

test('commit racing release leaves the order in exactly one state', async () => {
  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
  const [committed, released] = await Promise.allSettled([svc.commit('o1'), svc.release('o1')]);
  const outcomes = [committed.status, released.status].sort();
  assert.deepEqual(outcomes, ['fulfilled', 'rejected']);
  const loser = committed.status === 'rejected' ? committed : released;
  assert.ok(loser.reason instanceof OrderStateError);
  const expected = committed.status === 'fulfilled'
    ? { sku: 'widget', stock: 7, reserved: 0, sold: 3 }
    : { sku: 'widget', stock: 10, reserved: 0, sold: 0 };
  assert.deepEqual(await svc.snapshot('widget'), expected);
});

test('expire leaves committed and released orders alone', async () => {
  let t = 0;
  const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('sold', [{ sku: 'widget', qty: 2 }]);
  await svc.reserve('cancelled', [{ sku: 'widget', qty: 3 }]);
  await svc.reserve('abandoned', [{ sku: 'widget', qty: 4 }]);
  await svc.commit('sold');
  await svc.release('cancelled');
  t = 5000;
  assert.deepEqual(await svc.expire(), ['abandoned']);
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 8, reserved: 0, sold: 2 });
  assert.equal((await svc.commit('sold')).status, 'committed');
  assert.deepEqual(await svc.expire(), []);
});

test('expire racing commit either sells the order or releases it', async () => {
  let t = 0;
  const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  t = 5000;
  const [commit, expired] = await Promise.allSettled([svc.commit('o1'), svc.expire()]);
  assert.equal(expired.status, 'fulfilled');
  if (commit.status === 'fulfilled') {
    assert.deepEqual(expired.value, []);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 8, reserved: 0, sold: 2 });
  } else {
    assert.ok(commit.reason instanceof OrderStateError);
    assert.deepEqual(expired.value, ['o1']);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
  }
});

// --- a retried checkout held units twice -------------------------------------

test('concurrent retries of one order hold its stock once', async () => {
  const svc = await service();
  const attempts = await Promise.all(range(3).map(() => svc.reserve('o1', [{ sku: 'widget', qty: 2 }])));
  for (const attempt of attempts) {
    assert.deepEqual(attempt, { orderId: 'o1', status: 'reserved', items: [{ sku: 'widget', qty: 2 }] });
  }
  assert.equal(await svc.available('widget'), 8);
  await svc.commit('o1');
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 8, reserved: 0, sold: 2 });
});

// --- a rejected bundle left its other item held -------------------------------

test('a bundle with a short item holds none of its items', async () => {
  const svc = await service({ shoe: 5, lace: 1 });
  await assert.rejects(
    svc.reserve('o1', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 2 }]),
    InsufficientStockError
  );
  await assert.rejects(
    svc.reserve('o2', [{ sku: 'shoe', qty: 1 }, { sku: 'missing', qty: 1 }]),
    UnknownSkuError
  );
  assert.equal(await svc.available('shoe'), 5);
  assert.equal(await svc.available('lace'), 1);
  await assert.rejects(svc.commit('o1'), UnknownOrderError);
});

test('bundles competing for the last unit hold only the winner', async () => {
  const svc = await service({ shoe: 5, lace: 1 });
  const results = await Promise.allSettled([
    svc.reserve('o1', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]),
    svc.reserve('o2', [{ sku: 'lace', qty: 1 }, { sku: 'shoe', qty: 2 }])
  ]);
  const winners = results.filter(r => r.status === 'fulfilled');
  assert.equal(winners.length, 1);
  const shoeQty = winners[0].value.items.find(item => item.sku === 'shoe').qty;
  assert.equal(await svc.available('shoe'), 5 - shoeQty);
  assert.equal(await svc.available('lace'), 0);
});

// --- sold higher than orders shipped ------------------------------------------

test('concurrent commits of one order sell its units once', async () => {
  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
  const results = await Promise.all(range(3).map(() => svc.commit('o1')));
  assert.ok(results.every(r => r.status === 'committed'));
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
});

// --- throughput: no service-wide lock (INC-5490) ------------------------------

// A store whose writes to one key hang until the test lets them through.
function stallingStore(stallKey) {
  const store = new Store();
  const write = store.set.bind(store);
  let armed = false;
  let reached;
  let open;
  const stalled = new Promise(resolve => { reached = resolve; });
  const gate = new Promise(resolve => { open = resolve; });
  store.set = async (key, value) => {
    if (armed && key === stallKey) {
      reached();
      await gate;
    }
    return write(key, value);
  };
  return { store, arm: () => { armed = true; }, stalled, open };
}

test('calls on other skus and orders do not wait for a stalled call', { timeout: 5000 }, async () => {
  const { store, arm, stalled, open } = stallingStore('sku:shoe');
  const svc = new InventoryService({ store, now: () => 0, reservationTtlMs: 1000 });
  await svc.addStock('shoe', 5);
  await svc.addStock('hat', 5);
  arm();

  const stuck = svc.reserve('o1', [{ sku: 'shoe', qty: 1 }]);
  await stalled;
  let sameSkuDone = false;
  const sameSku = svc.reserve('o2', [{ sku: 'shoe', qty: 1 }]).then(() => { sameSkuDone = true; });

  // None of these touch the shoe sku or orders o1/o2.
  await svc.addStock('hat', 1);
  await svc.reserve('o3', [{ sku: 'hat', qty: 2 }]);
  await svc.commit('o3');
  await svc.reserve('o4', [{ sku: 'hat', qty: 1 }]);
  await svc.release('o4');
  assert.equal(await svc.available('shoe'), 5);
  assert.deepEqual(await svc.snapshot('hat'), { sku: 'hat', stock: 4, reserved: 0, sold: 2 });
  assert.equal(sameSkuDone, false);

  open();
  await Promise.all([stuck, sameSku]);
  assert.equal(await svc.available('shoe'), 3);
});

// --- randomized interleavings -------------------------------------------------

// Deterministic PRNG so a failing seed can be replayed.
function mulberry32(seed) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let x = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x;
    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
  };
}

// A store that adds a random number of event-loop turns before every call,
// so concurrent calls interleave differently on every seed.
function jitteryStore(random) {
  const store = new Store();
  for (const method of ['get', 'set', 'keys']) {
    const call = store[method].bind(store);
    store[method] = async (...args) => {
      const turns = Math.floor(random() * 4);
      for (let i = 0; i < turns; i++) {
        await new Promise(resolve => setImmediate(resolve));
      }
      return call(...args);
    };
  }
  return store;
}

test('counters match order states under random interleavings', async () => {
  const skus = ['shoe', 'lace', 'hat'];
  const expectedErrors = [InsufficientStockError, UnknownOrderError, OrderStateError];
  for (let seed = 1; seed <= 25; seed++) {
    const random = mulberry32(seed);
    const pick = list => list[Math.floor(random() * list.length)];
    const store = jitteryStore(random);
    let t = 0;
    const svc = new InventoryService({ store, now: () => t++, reservationTtlMs: 40 });
    const added = {};
    for (const sku of skus) {
      await svc.addStock(sku, 8);
      added[sku] = 8;
    }

    const calls = range(250).map(() => {
      const orderId = `o${Math.floor(random() * 60)}`;
      const roll = random();
      if (roll < 0.45) {
        const items = skus.filter(() => random() < 0.5).map(sku => ({ sku, qty: 1 + Math.floor(random() * 3) }));
        return svc.reserve(orderId, items.length ? items : [{ sku: pick(skus), qty: 1 }]);
      }
      if (roll < 0.7) {
        return svc.commit(orderId);
      }
      if (roll < 0.85) {
        return svc.release(orderId);
      }
      if (roll < 0.95) {
        const sku = pick(skus);
        const qty = 1 + Math.floor(random() * 3);
        return svc.addStock(sku, qty).then(result => {
          added[sku] += qty;
          return result;
        });
      }
      return svc.expire();
    });

    const results = await Promise.allSettled(calls);
    for (const result of results) {
      if (result.status === 'rejected' && !expectedErrors.some(type => result.reason instanceof type)) {
        throw result.reason;
      }
    }

    const orders = await Promise.all((await store.keys('order:')).map(key => store.get(key)));
    for (const sku of skus) {
      const units = status => orders
        .filter(order => order.status === status)
        .flatMap(order => order.items)
        .filter(item => item.sku === sku)
        .reduce((sum, item) => sum + item.qty, 0);
      const sold = units('committed');
      assert.deepEqual(
        await svc.snapshot(sku),
        { sku, stock: added[sku] - sold, reserved: units('reserved'), sold },
        `seed ${seed}, sku ${sku}`
      );
      assert.ok((await svc.available(sku)) >= 0, `seed ${seed}, sku ${sku}`);
    }
  }
});

