test('commits running alongside reserves on the same sku keep every hold', async () => {
  const svc = await service({ widget: 10 });
  for (const i of range(5)) {
    await svc.reserve(`old${i}`, [{ sku: 'widget', qty: 1 }]);
  }
  await Promise.all([
    ...range(5).map(i => svc.commit(`old${i}`)),
