  await svc.addStock('shoe', 5);
  await svc.addStock('hat', 5);
  arm();

  const stuck = svc.reserve('o1', [{ sku: 'shoe', qty: 1 }]);
  await stalled;
  let sameSkuDone = false;
  const sameSku = svc.reserve('o2', [{ sku: 'shoe', qty: 1 }]).then(() => { sameSkuDone = true; });

  // None of these touch the shoe sku or orders o1/o2.
  await svc.addStock('hat', 1);
  await svc.reserve('o3', [{ sku: 'hat', qty: 2 }]);
  await svc.commit('o3');
  await svc.reserve('o4', [{ sku: 'hat', qty: 1 }]);
  await svc.release('o4');
