// A store that adds a random number of event-loop turns before every call,
// so concurrent calls interleave differently on every seed.
function jitteryStore(random) {
  const store = new Store();
  for (const method of ['get', 'set', 'keys']) {
    const call = store[method].bind(store);
    store[method] = async (...args) => {
      const turns = Math.floor(random() * 4);
      for (let i = 0; i < turns; i++) {
        await new Promise(resolve => setImmediate(resolve));
      }
      return call(...args);
    };
  }
  return store;
}

test('counters match order states under random interleavings', async () => {
  const skus = ['shoe', 'lace', 'hat'];
  const expectedErrors = [InsufficientStockError, UnknownOrderError, OrderStateError];
  for (let seed = 1; seed <= 25; seed++) {
    const random = mulberry32(seed);
    const pick = list => list[Math.floor(random() * list.length)];
    const store = jitteryStore(random);
    let t = 0;
    const svc = new InventoryService({ store, now: () => t++, reservationTtlMs: 40 });
    const added = {};
    for (const sku of skus) {
      await svc.addStock(sku, 8);
      added[sku] = 8;
    }

    const calls = range(250).map(() => {
      const orderId = `o${Math.floor(random() * 60)}`;
      const roll = random();
      if (roll < 0.45) {
        const items = skus.filter(() => random() < 0.5).map(sku => ({ sku, qty: 1 + Math.floor(random() * 3) }));
        return svc.reserve(orderId, items.length ? items : [{ sku: pick(skus), qty: 1 }]);
      }
      if (roll < 0.7) {
        return svc.commit(orderId);
      }
      if (roll < 0.85) {
        return svc.release(orderId);
      }
      if (roll < 0.95) {
        const sku = pick(skus);
        const qty = 1 + Math.floor(random() * 3);
        return svc.addStock(sku, qty).then(result => {
          added[sku] += qty;
          return result;
        });
      }
      return svc.expire();
    });

    const results = await Promise.allSettled(calls);
    for (const result of results) {
      if (result.status === 'rejected' && !expectedErrors.some(type => result.reason instanceof type)) {
        throw result.reason;
      }
    }

    const orders = await Promise.all((await store.keys('order:')).map(key => store.get(key)));
    for (const sku of skus) {
      const units = status => orders
        .filter(order => order.status === status)
        .flatMap(order => order.items)
        .filter(item => item.sku === sku)
        .reduce((sum, item) => sum + item.qty, 0);
      const sold = units('committed');
      assert.deepEqual(
        await svc.snapshot(sku),
        { sku, stock: added[sku] - sold, reserved: units('reserved'), sold },
        `seed ${seed}, sku ${sku}`
      );
      assert.ok((await svc.available(sku)) >= 0, `seed ${seed}, sku ${sku}`);
    }
  }
});

