'use strict';

// Mutual exclusion per key. A call locks only the keys it touches, so calls
// on disjoint keys never wait for each other. Waiters are served in arrival
// order.
class KeyedLocks {
  constructor() {
    // key -> callers waiting for it; a key is locked while it has an entry.
    this.waiting = new Map();
  }

  /**
   * Run `fn` while holding the lock on every key. Keys are locked in sorted
   * order so that calls needing overlapping keys cannot deadlock.
   */
  async run(keys, fn) {
    const held = [];
    try {
      for (const key of [...new Set(keys)].sort()) {
        await this.lock(key);
        held.push(key);
      }
      return await fn();
    } finally {
      for (const key of held.reverse()) {
        this.unlock(key);
      }
    }
  }

  lock(key) {
    const queue = this.waiting.get(key);
    if (!queue) {
      this.waiting.set(key, []);
      return Promise.resolve();
    }
    return new Promise(resolve => queue.push(resolve));
  }

  unlock(key) {
    const next = this.waiting.get(key).shift();
    if (next) {
      next();
    } else {
      this.waiting.delete(key);
    }
  }
}

module.exports = { KeyedLocks };

