    assertQty(qty);
    return withLocks(this.store, [skuKey(sku)], async () => {
      const item = (await this.store.get(skuKey(sku))) || { stock: 0, reserved: 0, sold: 0 };
      const updated = { ...item, stock: item.stock + qty };
      await this.store.set(skuKey(sku), updated);
      return { sku, ...updated };
    });
  }

  /** Units that can still be reserved. */
  async available(sku) {
    const item = await this.getItem(sku);
    return item.stock - item.reserved;
  }

  /** The SKU's counters. */
  async snapshot(sku) {
    const item = await this.getItem(sku);
    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
  }

  /**
   * Hold stock for an order: all of its items, or none of them.
   *
   * Idempotent by orderId: checkout retries a timed-out request with the same
   * orderId, and a retry must return the existing reservation rather than
   * hold the stock twice.
   *
   * Rejects with InsufficientStockError when any item cannot be held, and
   * then holds nothing.
   */
  async reserve(orderId, items) {
    assertOrderId(orderId);
    assertItems(items);
    // Copy before the first await: the caller's array may change meanwhile.
    const lines = items.map(({ sku, qty }) => ({ sku, qty }));
    return withLocks(this.store, [orderKey(orderId)], async () => {
      const existing = await this.store.get(orderKey(orderId));
      if (existing) {
        return toReservation(existing);
      }
      await withLocks(this.store, lines.map(({ sku }) => skuKey(sku)), async () => {
        // Check every item before holding any of them.
        const held = [];
        for (const { sku, qty } of lines) {
          const item = await this.getItem(sku);
          const free = item.stock - item.reserved;
          if (free < qty) {
            throw new InsufficientStockError(sku, qty, free);
          }
          held.push({ sku, item: { ...item, reserved: item.reserved + qty } });
        }
        for (const { sku, item } of held) {
          await this.store.set(skuKey(sku), item);
        }
      });
      const order = { orderId, items: lines, status: 'reserved', createdAt: this.now() };
      await this.store.set(orderKey(orderId), order);
      return toReservation(order);
    });
  }

  /**
   * Turn a reservation into a sale. Idempotent: committing a committed order
   * returns it unchanged. A released order cannot be committed.
   */
  async commit(orderId) {
    assertOrderId(orderId);
    return withLocks(this.store, [orderKey(orderId)], async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'committed') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'commit');
      }
      return this.#settle(order, 'committed', sellHeld);
    });
  }

  /**
   * Cancel a reservation and return its units. Idempotent: releasing a
   * released order returns it unchanged. A committed order cannot be
   * released; its units have been sold.
   */
  async release(orderId) {
    assertOrderId(orderId);
    return withLocks(this.store, [orderKey(orderId)], async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'released') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'release');
      }
      return this.#settle(order, 'released', returnHeld);
    });
  }

  /**
   * Release every reservation older than the TTL that has not been committed
   * or released. Returns the orderIds it released.
   */
  async expire() {
    const cutoff = this.now() - this.ttl;
    const released = [];
    for (const key of await this.store.keys('order:')) {
      // Read under the order's lock: a commit or release may land between
      // listing the keys and getting here.
      const orderId = await withLocks(this.store, [key], async () => {
        const order = await this.store.get(key);
        if (order.status !== 'reserved' || order.createdAt >= cutoff) {
          return null;
        }
        await this.#settle(order, 'released', returnHeld);
        return order.orderId;
      });
      if (orderId !== null) {
        released.push(orderId);
      }
    }
    return released;
  }

  async getItem(sku) {
    assertSku(sku);
    const item = await this.store.get(skuKey(sku));
    if (!item) {
      throw new UnknownSkuError(sku);
    }
    return item;
  }

  async getOrder(orderId) {
    assertOrderId(orderId);
    const order = await this.store.get(orderKey(orderId));
    if (!order) {
      throw new UnknownOrderError(orderId);
    }
    return order;
  }

  // Move a reserved order to `status`, applying `change` to the counters of
  // each of its SKUs. The caller holds the order's lock, which keeps anyone
  // else from acting on the order until its new status is written.
  async #settle(order, status, change) {
    await withLocks(this.store, order.items.map(({ sku }) => skuKey(sku)), async () => {
      for (const { sku, qty } of order.items) {
        const item = await this.getItem(sku);
        await this.store.set(skuKey(sku), change(item, qty));
      }
    });
    const settled = { ...order, status };
    await this.store.set(orderKey(order.orderId), settled);
    return toReservation(settled);
  }
}

function sellHeld(item, qty) {
  return { ...item, stock: item.stock - qty, reserved: item.reserved - qty, sold: item.sold + qty };
}

function returnHeld(item, qty) {
  return { ...item, reserved: item.reserved - qty };
}

// Locks belong to the store, not the service, so services that share a store
// also exclude each other. Lock keys are the store keys they protect.
const locksByStore = new WeakMap();

function withLocks(store, keys, fn) {
  let locks = locksByStore.get(store);
  if (!locks) {
    locks = new KeyedLocks();
    locksByStore.set(store, locks);
  }
  return locks.run(keys, fn);
}

